import React from "react";
import { useTranslation } from "react-i18next";
import { navigate } from "gatsby";

interface ButtonProps {
  isDisabled: boolean;
  isSubmit?: boolean;
  sending?: boolean;
  labelKey?: string;
}

const ButtonComponent = ({
  isDisabled,
  isSubmit = false,
  sending = false,
  labelKey = "contact.form.send",
}: ButtonProps) => {
  const { t } = useTranslation();

  const handleClick = () => {
    if (!isSubmit) {
      navigate("/contact");
    }
  };


  return (
    <button
      type={isSubmit ? "submit" : "button"}
      onClick={handleClick}
      disabled={isDisabled}
      className={`
        ${isDisabled ? "opacity-20 cursor-not-allowed" : ""}
        w-full border
        body-mob sm:body
        !backdrop-blur-md 
        rounded-lg py-4 px-4 body-4
        border-LightGrayText hover:border-Yellow 
        bg-white/10 hover:bg-white/20 
        active:bg-Yellow
        active:border-LightGrayText active:text-DarkGreen`}
    >
      {t(labelKey)}
    </button>
  );
};

export default ButtonComponent;
